# rotate_right :: ([1, 2, 3, 4, 5], 2)
def rotate_right(xs, k):
    if not xs:
        return xs
    k = k % len(xs)
    return xs[-k:] + xs[:-k]

if __name__ == '__main__':
    print(rotate_right(([1, 2, 3, 4, 5], 2)))

